export type YouTubeInterfaceProps = Record<string, any>;

const CATEGORIES = ["All", "Gaming", "Music", "Live", "Mixes", "Computers", "Programming", "Podcasts", "News", "Recently uploaded"];
const MOCK_VIDEOS = [
  { views: "25K watching • LIVE", color: "#2E294E" },
  { views: "1.1M views • 2 days ago", color: "#546A7B" },
  { views: "85K views • 18 hours ago", color: "#9B5DE5" },
  { views: "12M views • 1 week ago", color: "#F15BB5" },
  { views: "48K views • 3 days ago", color: "#00BBF9" },
];

const VideoCard = ({
  index,
  isHero,
  thumbnail,
  title,
  channel,
  views,
  avatar,
  baseDelay,
  heroScale = 1
}: {
  index: number;
  isHero?: boolean;
  thumbnail?: string;
  title: string;
  channel: string;
  views: string;
  avatar?: string;
  baseDelay: number;
  heroScale?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animations
  const enterDelay = baseDelay + index * 3;
  const opacity = interpolate(frame, [enterDelay, enterDelay + 15], [0, 1], { extrapolateRight: "clamp" });
  const translateY = spring({ frame: frame - enterDelay, fps, from: 50, to: 0, config: { damping: 15 } });

  // Hover Effect for Hero
  const scale = isHero ? spring({
    frame: frame - 45, // Wait for entrance to finish
    fps,
    from: 1,
    to: 1.03,
    config: { stiffness: 60 }
  }) : 1;

  const showVideo = interpolate(frame, [0, 1], [1, 1]); // Always show

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 12,
        opacity,
        transform: `translateY(${translateY}px) scale(${scale})`,
        transformOrigin: "center center",
      }}
    >
      {/* Thumbnail */}
      <div style={{
        position: "relative",
        width: "100%",
        aspectRatio: "16/9",
        backgroundColor: isHero ? "#000" : "#ddd",
        borderRadius: 12,
        overflow: "hidden",
        boxShadow: isHero ? "0 4px 20px rgba(0,0,0,0.15)" : "none"
      }}>
        {thumbnail ? (
          <Img src={thumbnail} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <div style={{ width: "100%", height: "100%", background: `linear-gradient(45deg, #333, #666)` }} />
        )}
        <div style={{
          position: "absolute",
          bottom: 8,
          right: 8,
          backgroundColor: "rgba(0,0,0,0.8)",
          color: "white",
          padding: "3px 6px",
          borderRadius: 4,
          fontSize: 12,
          fontWeight: 600
        }}>
          {isHero ? "14:20" : "8:45"}
        </div>
      </div>

      {/* Meta */}
      <div style={{ display: "flex", gap: 12 }}>
        {/* Avatar */}
        <div style={{
          width: 36, height: 36, borderRadius: "50%",
          backgroundColor: isHero ? "#3ea6ff" : "#aaa",
          overflow: "hidden",
          flexShrink: 0
        }}>
          {avatar && <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />}
        </div>

        {/* Text Info */}
        <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          <div style={{
            fontSize: 16,
            fontWeight: 700,
            color: "#0f0f0f",
            lineHeight: 1.2,
            maxHeight: 40,
            overflow: "hidden"
          }}>
            {title}
          </div>
          <div style={{ fontSize: 14, color: "#606060", display: "flex", flexDirection: "column" }}>
            <span>{channel}</span>
            <span>{views}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

